import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';

import 'canvasser_home.dart';
// Generated by running `flutterfire configure`.
import 'firebase_options.dart';
import 'firestore_service.dart';
import 'login_screen.dart';
import 'models.dart';
import 'organizer_home.dart';
import 'widgets.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const DemoApp());
}

class DemoApp extends StatelessWidget {
  const DemoApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Canvassing Demo',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.indigo,
        useMaterial3: true,
        visualDensity: VisualDensity.adaptivePlatformDensity,
        inputDecorationTheme: InputDecorationTheme(
          border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
        ),
        filledButtonTheme: FilledButtonThemeData(
          style: FilledButton.styleFrom(
            minimumSize: const Size.fromHeight(52),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
            ),
          ),
        ),
      ),
      home: const AuthGate(),
    );
  }
}

/// Login page when signed out; otherwise on to the role check.
class AuthGate extends StatelessWidget {
  const AuthGate({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<User?>(
      stream: FirebaseAuth.instance.authStateChanges(),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const _Loading();
        }
        final user = snapshot.data;
        if (user == null) return const LoginScreen();
        return RoleGate(uid: user.uid);
      },
    );
  }
}

/// Reads the signed-in user's profile and opens the screen for their role.
class RoleGate extends StatelessWidget {
  final String uid;
  const RoleGate({super.key, required this.uid});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: Db.profileStream(uid),
      builder: (context, snap) {
        if (snap.hasError) {
          return Scaffold(
            appBar: AppBar(
              title: const Text('Canvassing Demo'),
              actions: [
                IconButton(
                  tooltip: 'Log out',
                  icon: const Icon(Icons.logout),
                  onPressed: () => FirebaseAuth.instance.signOut(),
                ),
              ],
            ),
            body: MessageView(
              icon: Icons.cloud_off,
              title: "Couldn't load your profile",
              message:
                  'Check that Firestore is created and the security rules are published.\n\n${snap.error}',
            ),
          );
        }

        final doc = snap.data;
        if (doc == null) return const _Loading();

        if (doc.exists) {
          final user = AppUser.fromDoc(doc);
          return user.role == UserRole.organizer
              ? OrganizerHome(user: user)
              : CanvasserHome(user: user);
        }

        // No profile yet: either sign-up is still writing it, or this is an
        // older account made before roles existed.
        return ValueListenableBuilder<bool>(
          valueListenable: signUpInProgress,
          builder: (context, busy, _) =>
              busy ? const _Loading() : const RolePickerScreen(),
        );
      },
    );
  }
}

class _Loading extends StatelessWidget {
  const _Loading();

  @override
  Widget build(BuildContext context) {
    return const Scaffold(body: Center(child: CircularProgressIndicator()));
  }
}

/// Shown to accounts that don't have a role yet.
class RolePickerScreen extends StatefulWidget {
  const RolePickerScreen({super.key});

  @override
  State<RolePickerScreen> createState() => _RolePickerScreenState();
}

class _RolePickerScreenState extends State<RolePickerScreen> {
  UserRole _role = UserRole.canvasser;
  bool _saving = false;
  String? _error;

  Future<void> _continue() async {
    setState(() {
      _saving = true;
      _error = null;
    });
    try {
      await Db.createProfile(_role);
      // RoleGate notices the new profile and opens the right screen.
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _saving = false;
        _error = '$e';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return Scaffold(
      body: SafeArea(
        child: Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.all(20),
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 420),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Icon(Icons.badge_outlined, size: 56, color: scheme.primary),
                  const SizedBox(height: 16),
                  Text(
                    'Choose your role',
                    textAlign: TextAlign.center,
                    style: Theme.of(context).textTheme.headlineSmall,
                  ),
                  const SizedBox(height: 8),
                  const Text(
                    'Organizers plan routes and review results. '
                    'Canvassers follow assigned routes and record surveys.',
                    textAlign: TextAlign.center,
                  ),
                  const SizedBox(height: 24),
                  SegmentedButton<UserRole>(
                    showSelectedIcon: false,
                    segments: const [
                      ButtonSegment(
                        value: UserRole.canvasser,
                        icon: Icon(Icons.directions_walk),
                        label: Text('Canvasser'),
                      ),
                      ButtonSegment(
                        value: UserRole.organizer,
                        icon: Icon(Icons.edit_location_alt_outlined),
                        label: Text('Organizer'),
                      ),
                    ],
                    selected: {_role},
                    onSelectionChanged: (s) => setState(() => _role = s.first),
                  ),
                  if (_error != null) ...[
                    const SizedBox(height: 12),
                    Text(_error!, style: TextStyle(color: scheme.error)),
                  ],
                  const SizedBox(height: 24),
                  FilledButton(
                    onPressed: _saving ? null : _continue,
                    child: _saving
                        ? const SizedBox(
                            width: 22,
                            height: 22,
                            child: CircularProgressIndicator(strokeWidth: 2.5),
                          )
                        : const Text('Continue'),
                  ),
                  TextButton(
                    onPressed: _saving
                        ? null
                        : () => FirebaseAuth.instance.signOut(),
                    child: const Text('Log out'),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}
